static int MeleePc_IsSheikFigaTreeProfile(uint32_t length, uint32_t body,
        uint32_t relocs, uint32_t root, const char* name)
{
    for (size_t i = 0; i < sizeof(melee_pc_sheik_figatree_profiles) /
                         sizeof(melee_pc_sheik_figatree_profiles[0]); ++i) {
        const MeleePc_SheikFigaTreeProfile* p = &melee_pc_sheik_figatree_profiles[i];
        if (length == p->length && body == p->body && relocs == p->relocs &&
            root == p->root && !strcmp(name, p->name)) return 1;
    }
    return 0;
}
